/* Hidden attribute override guarantee */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b213a;
  --card-bg: #3f3156;
  --accent-gold: #ffbe3b;
  --accent-white: #ffffff;
  --accent-yolk: #ff8e2b;
  --text-primary: #f8f6f0;
  --text-muted: #d0c8dd;
  --border-color: #171120;
  --progress-bg: #221830;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Courier New", monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-color);
  color: var(--text-primary);
  font-family: var(--font-family);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 440px;
  min-width: 320px;
}

.header {
  text-align: center;
  margin-bottom: 16px;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent-gold);
  text-shadow: 2px 2px 0 var(--border-color);
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border-color);
  box-shadow: 6px 6px 0 var(--border-color);
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

/* Pure CSS Pixel Egg Art */
.egg-stage {
  height: 96px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pixel-egg {
  width: 8px;
  height: 8px;
  background-color: transparent;
  /* Render 10x12 grid pixel egg using box-shadow */
  box-shadow:
    /* Row 1 */
    24px 0 var(--border-color), 32px 0 var(--border-color),
    /* Row 2 */
    16px 8px var(--border-color), 24px 8px var(--accent-white), 32px 8px var(--accent-white), 40px 8px var(--border-color),
    /* Row 3 */
    8px 16px var(--border-color), 16px 16px var(--accent-white), 24px 16px var(--accent-white), 32px 16px var(--accent-white), 40px 16px var(--accent-white), 48px 16px var(--border-color),
    /* Row 4 */
    8px 24px var(--border-color), 16px 24px var(--accent-white), 24px 24px var(--accent-gold), 32px 24px var(--accent-gold), 40px 24px var(--accent-white), 48px 24px var(--border-color),
    /* Row 5 */
    0px 32px var(--border-color), 8px 32px var(--accent-white), 16px 32px var(--accent-gold), 24px 32px var(--accent-yolk), 32px 32px var(--accent-gold), 40px 32px var(--accent-white), 48px 32px var(--accent-white), 56px 32px var(--border-color),
    /* Row 6 */
    0px 40px var(--border-color), 8px 40px var(--accent-white), 16px 40px var(--accent-gold), 24px 40px var(--accent-yolk), 32px 40px var(--accent-gold), 40px 40px var(--accent-white), 48px 40px var(--accent-white), 56px 40px var(--border-color),
    /* Row 7 */
    0px 48px var(--border-color), 8px 48px var(--accent-white), 16px 48px var(--accent-white), 24px 48px var(--accent-gold), 32px 48px var(--accent-gold), 40px 48px var(--accent-white), 48px 48px var(--accent-white), 56px 48px var(--border-color),
    /* Row 8 */
    8px 56px var(--border-color), 16px 56px var(--accent-white), 24px 56px var(--accent-white), 32px 56px var(--accent-white), 40px 56px var(--accent-white), 48px 56px var(--border-color),
    /* Row 9 */
    16px 64px var(--border-color), 24px 64px var(--border-color), 32px 64px var(--border-color), 40px 64px var(--border-color);
  transform: translate(-28px, -32px);
  transition: transform 0.2s ease;
}

.egg-stage.cooking .pixel-egg {
  animation: pixel-wobble 1.2s infinite steps(2, start);
}

.egg-stage.done .pixel-egg {
  animation: pixel-jump 0.6s infinite alternate steps(2, start);
}

@keyframes pixel-wobble {
  0% { transform: translate(-28px, -32px) rotate(0deg); }
  50% { transform: translate(-26px, -32px) rotate(4deg); }
  100% { transform: translate(-30px, -32px) rotate(-4deg); }
}

@keyframes pixel-jump {
  0% { transform: translate(-28px, -32px); }
  100% { transform: translate(-28px, -44px); }
}

/* Buttons */
.preset-group {
  display: flex;
  flex-direction: column;
  width: 100%;
  gap: 10px;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 14px;
  background: #503d6e;
  color: var(--text-primary);
  border: 3px solid var(--border-color);
  box-shadow: 3px 3px 0 var(--border-color);
  cursor: pointer;
  text-align: center;
  text-decoration: none;
  outline: none;
  user-select: none;
  transition: background-color 0.1s, transform 0.05s, box-shadow 0.05s;
}

.btn:hover:not(:disabled) {
  background: #624b86;
}

.btn:focus-visible {
  outline: 3px solid var(--accent-gold);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 var(--border-color);
}

.btn.active {
  background: var(--accent-gold);
  color: var(--border-color);
  border-color: var(--border-color);
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

/* Timer Display */
.timer-display-box {
  width: 100%;
  text-align: center;
}

.time-text {
  font-size: 2.75rem;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--accent-gold);
  text-shadow: 2px 2px 0 var(--border-color);
  margin-bottom: 12px;
  font-variant-numeric: tabular-nums;
}

/* Progress Bar */
.progress-track {
  width: 100%;
  height: 18px;
  background-color: var(--progress-bg);
  border: 3px solid var(--border-color);
  box-shadow: inset 2px 2px 0 rgba(0, 0, 0, 0.4);
  overflow: hidden;
  position: relative;
}

.progress-fill {
  width: 0%;
  height: 100%;
  background-color: var(--accent-gold);
  transition: width 0.3s ease;
}

/* Action Buttons */
.action-group {
  display: flex;
  gap: 10px;
  width: 100%;
}

.action-btn {
  flex: 1;
}

.btn-secondary {
  background: #39284d;
}

/* Status Banner */
.status-banner {
  width: 100%;
  padding: 12px;
  background-color: var(--accent-gold);
  color: var(--border-color);
  font-weight: 800;
  font-size: 1.2rem;
  text-align: center;
  border: 3px solid var(--border-color);
  box-shadow: 4px 4px 0 var(--border-color);
  animation: flash 1s infinite alternate steps(2, start);
}

@keyframes flash {
  0% { transform: scale(1); }
  100% { transform: scale(1.03); }
}

/* Responsive Tweaks */
@media (min-width: 400px) {
  .preset-group {
    flex-direction: row;
  }
  .preset-btn {
    flex: 1;
    padding: 10px 4px;
    font-size: 0.95rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // DOM Elements
  const btnSoft = document.getElementById('btnSoft');
  const btnMedium = document.getElementById('btnMedium');
  const btnHard = document.getElementById('btnHard');
  const presetButtons = [btnSoft, btnMedium, btnHard];

  const btnPause = document.getElementById('btnPause');
  const btnResume = document.getElementById('btnResume');
  const btnReset = document.getElementById('btnReset');

  const timeDisplay = document.getElementById('timeDisplay');
  const progressFill = document.getElementById('progressFill');
  const progressBar = document.getElementById('progressBar');
  const statusBanner = document.getElementById('statusBanner');
  const eggStage = document.querySelector('.egg-stage');

  // State Variables
  let totalSeconds = 0;
  let remainingSeconds = 0;
  let timerInterval = null;
  let isPaused = false;
  let isRunning = false;

  function formatTime(totalSec) {
    const minutes = Math.floor(totalSec / 60);
    const seconds = totalSec % 60;
    const paddedSeconds = seconds < 10 ? `0${seconds}` : seconds;
    return `${minutes}:${paddedSeconds}`;
  }

  function updateUI() {
    // Format time display as m:ss
    timeDisplay.textContent = formatTime(remainingSeconds);

    // Update progress bar percentage (0 to 100)
    let percent = 0;
    if (totalSeconds > 0) {
      const elapsed = totalSeconds - remainingSeconds;
      percent = Math.min(100, Math.max(0, (elapsed / totalSeconds) * 100));
    }
    progressFill.style.width = `${percent}%`;
    progressBar.setAttribute('aria-valuenow', Math.round(percent).toString());
  }

  function clearTimerInterval() {
    if (timerInterval !== null) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
  }

  function startTimer(seconds) {
    clearTimerInterval();
    totalSeconds = seconds;
    remainingSeconds = seconds;
    isRunning = true;
    isPaused = false;

    // Hide any previous completion message
    statusBanner.hidden = true;
    eggStage.classList.remove('done');
    eggStage.classList.add('cooking');

    // Controls state
    btnPause.disabled = false;
    btnResume.disabled = true;
    btnReset.disabled = false;

    updateUI();

    timerInterval = setInterval(() => {
      if (remainingSeconds > 0) {
        remainingSeconds -= 1;
        updateUI();
      }

      if (remainingSeconds <= 0) {
        completeTimer();
      }
    }, 1000);
  }

  function pauseTimer() {
    if (!isRunning || isPaused) return;
    clearTimerInterval();
    isPaused = true;
    isRunning = false;

    btnPause.disabled = true;
    btnResume.disabled = false;
    eggStage.classList.remove('cooking');
  }

  function resumeTimer() {
    if (!isPaused || remainingSeconds <= 0) return;
    isPaused = false;
    isRunning = true;

    btnPause.disabled = false;
    btnResume.disabled = true;
    eggStage.classList.add('cooking');

    timerInterval = setInterval(() => {
      if (remainingSeconds > 0) {
        remainingSeconds -= 1;
        updateUI();
      }

      if (remainingSeconds <= 0) {
        completeTimer();
      }
    }, 1000);
  }

  function completeTimer() {
    clearTimerInterval();
    isRunning = false;
    isPaused = false;
    remainingSeconds = 0;
    updateUI();

    btnPause.disabled = true;
    btnResume.disabled = true;
    eggStage.classList.remove('cooking');
    eggStage.classList.add('done');

    // Reveal completion notification
    statusBanner.hidden = false;
  }

  function resetTimer() {
    clearTimerInterval();
    isRunning = false;
    isPaused = false;
    totalSeconds = 0;
    remainingSeconds = 0;

    presetButtons.forEach(btn => btn.classList.remove('active'));
    btnPause.disabled = true;
    btnResume.disabled = true;
    btnReset.disabled = true;
    statusBanner.hidden = true;

    eggStage.classList.remove('cooking', 'done');
    updateUI();
  }

  function handlePresetClick(event) {
    const btn = event.currentTarget;
    const seconds = parseInt(btn.getAttribute('data-seconds'), 10);

    presetButtons.forEach(b => b.classList.remove('active'));
    btn.classList.add('active');

    startTimer(seconds);
  }

  // Event Listeners
  presetButtons.forEach(btn => {
    btn.addEventListener('click', handlePresetClick);
  });

  btnPause.addEventListener('click', pauseTimer);
  btnResume.addEventListener('click', resumeTimer);
  btnReset.addEventListener('click', resetTimer);

  // Initial UI Setup
  updateUI();
});
